// 提取论文数据中的所有年份
function extractAvailableYears() {
    const years = new Set();

    pinnsPapers.forEach(paper => {
        const yearMatch = paper.meta.date.match(/\d{4}/);
        if (yearMatch) {
            years.add(yearMatch[0]);
        }
    });

    // 将Set转换为数组并按年份降序排序（最新的在前）
    return Array.from(years).sort((a, b) => parseInt(b) - parseInt(a));
}

// 初始化自定义下拉组件
function initCustomSelects() {
    const customSelects = document.querySelectorAll('.custom-select');

    customSelects.forEach(select => {
        const trigger = select.querySelector('.custom-select-trigger');

        // 点击触发器
        trigger.addEventListener('click', (e) => {
            e.stopPropagation();
            const isOpen = select.classList.contains('open');
            closeAllSelects();
            if (!isOpen) {
                select.classList.add('open');
            }
        });
    });

    // 点击其他区域关闭所有下拉
    document.addEventListener('click', closeAllSelects);
}

function closeAllSelects() {
    document.querySelectorAll('.custom-select.open').forEach(select => {
        select.classList.remove('open');
    });
}

// 绑定下拉选项点击事件
function bindSelectOptions(select) {
    const trigger = select.querySelector('.custom-select-trigger');
    const options = select.querySelectorAll('.custom-select-option');

    options.forEach(option => {
        option.addEventListener('click', (e) => {
            e.stopPropagation();
            const value = option.dataset.value;
            const text = option.textContent;

            // 更新选中状态
            options.forEach(opt => opt.classList.remove('selected'));
            option.classList.add('selected');

            // 更新触发器文本
            trigger.textContent = text;

            // 关闭下拉
            select.classList.remove('open');

            // 触发筛选变化
            select.dispatchEvent(new CustomEvent('selectChange', {
                detail: { value: value, id: select.id }
            }));
        });
    });
}

// 动态填充年份筛选选项
function populateYearFilter() {
    const yearSelect = document.getElementById('yearSelect');
    if (!yearSelect) return;

    const availableYears = extractAvailableYears();
    const optionsContainer = yearSelect.querySelector('.custom-select-options');

    // 清空现有选项
    optionsContainer.innerHTML = '';

    // 添加"所有年份"选项
    const allOption = document.createElement('div');
    allOption.className = 'custom-select-option selected';
    allOption.dataset.value = '';
    allOption.textContent = '所有年份';
    optionsContainer.appendChild(allOption);

    // 添加实际存在的年份选项
    availableYears.forEach(year => {
        const optionDiv = document.createElement('div');
        optionDiv.className = 'custom-select-option';
        optionDiv.dataset.value = year;
        optionDiv.textContent = year;
        optionsContainer.appendChild(optionDiv);
    });

    // 绑定年份选项点击事件
    bindSelectOptions(yearSelect);
}

// Markdown格式处理函数 - 将Markdown格式转换为HTML格式
function processMarkdown(text) {
    if (!text) return '';

    console.log('原始文本:', text);

    // 处理加粗格式 **文本** -> <strong>文本</strong>
    text = text.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

    // 处理换行格式
    // 先将双换行替换为段落分隔符
    text = text.replace(/\n\n/g, '||PARAGRAPH||');

    // 将单换行替换为HTML换行
    text = text.replace(/\n/g, '<br>');

    // 将段落分隔符替换为段落标签
    text = text.replace(/\|\|PARAGRAPH\|\|/g, '</p><p>');

    // 确保文本被段落标签包裹
    if (!text.startsWith('<p>')) {
        text = '<p>' + text + '</p>';
    }

    console.log('处理后文本:', text);

    return text;
}



