                "experiments": "研究团队设计了多层次的验证实验。在函数逼近任务中，用4层50神经元网络拟合含高低频成分的非线性函数，自适应激活仅用22000次迭代就完全捕获所有频率，而固定激活在相同迭代次数下仍有明显误差。在Burgers方程（描述冲击波的经典PDE）求解中，固定激活的相对L²误差为19.1%，而使用n=10的自适应版本降至9.5%——精度翻倍！更有趣的是在Klein-Gordon方程（量子场论中的基础方程）中，频域分析显示：400次迭代时，自适应版本已捕获所有关键频率，固定版本却需要1500次以上。\n\n在二维sine-Gordon方程的逆问题中（从数据反推方程参数），即使训练数据含2%噪声，自适应方法识别的四个参数λ₁到λ₄的误差均低于1.4%，而固定激活最大误差达9.97%。标准深度学习基准测试（CIFAR-10/100, SVHN等7个数据集）显示，使用预激活ResNet-18架构时，自适应激活在所有数据集上都更快达到更低的训练损失，证明其普适性。",
