                "context": "传统逆向设计依赖数值求解器(如有限元、有限差分)配合伴随方法进行优化，虽然成熟但存在两大痛点：一是需要精细网格划分，计算成本随维度指数增长；二是依赖特定求解器实现，不同物理场需要不同的代码框架。近年物理信息神经网络(PINN)展现出求解PDE的潜力，但其软约束机制导致一个致命问题——在逆向设计中，目标函数与物理方程往往相互竞争，单纯最小化加权损失会让网络'偷懒'，既不完全满足方程也无法达到最优设计。",
