                "innovation": "① 架构创新：将算子逼近定理中的浅层网络推广到任意深度，并证明分支-主干结构是最小化泛化误差的最优设计；\n\n② 输入表示创新：提出多种函数离散化方法(传感器采样、谱展开、高斯随机场)，并通过理论分析和实验确定最优传感器数量；\n\n③ 训练效率突破：发现了'指数收敛区→多项式收敛区'的两阶段训练动态——小数据时呈指数级误差下降(远超经典学习理论的x⁻⁰·⁵速率)，大数据时转为多项式收敛。转折点随网络规模增大而后移，这一现象与信息瓶颈理论可能相关；\n\n④ 泛化能力验证：训练在相关长度l=0.5的高斯随机场上，测试在l=0.1的函数上，误差随两分布的Wasserstein距离呈指数增长——首次定量刻画了算子学习的泛化边界。"
