                "method": "方法核心分三步实现'智能采样'：\n\n ① 理论基础：研究团队借鉴已有理论结果，证明当采样概率与损失梯度的2范数成正比时，SGD的收敛速度最快。但直接计算所有配点的梯度范数太昂贵，因此采用损失值作为代理——理论和实验都表明，配点按损失值排序与按梯度范数排序高度一致。\n\n ② PWC近似：为进一步降低计算成本，不对每个配点都计算损失，而是在物理域内均匀撒一些'种子点'(数量远少于配点总数)，只在种子点计算损失。然后用最近邻搜索算法，将每个配点的损失设为其最近种子点的损失值——这相当于做Voronoi分割，每个单元内损失为常数。\n\n ③ 动态采样：每轮迭代先计算所有种子点的损失，通过PWC近似得到所有配点的损失估计，归一化后得到采样概率分布。从这个分布中抽取小批量配点，用重要性权重修正梯度(除以采样概率)，确保梯度估计无偏。\n\n 整个流程只需在原有PINNs代码基础上增加几行：生成种子点、最近邻搜索、按概率采样，实现极其简洁。",
