                        "subtitle": "模式的浮现",
                        "content": "这些复现实验揭示了几个令人不安的模式：\n\n**模式一：精度不匹配**。许多文章用高精度训练数据的求解器与低精度ML模型比速度，却没有降低基线的分辨率来匹配精度。这就像比较一辆豪华轿车和一辆自行车的速度，但不考虑它们去不同的目的地。\n\n**模式二：算法选择不当**。一些文章使用了对该PDE效率低下的数值方法。例如，对平滑解的问题使用一阶方法(极具扩散性且需要高网格分辨率)，或对对流占优问题使用隐式时间步进(通常导致低效)。\n\n**模式三：实现低效**。即使选择了合理的算法，实现也可能存在问题。作者发现一些文章的标准方法实现比他们自己的实现慢几个数量级。\n\n**模式四：选择性报告**。一些文章在摘要中报告与较弱基线的比较，但在正文或附录中实际上有与较强基线的比较——暗示作者可能意识到问题，但选择强调更积极的结果。",
