                "context": "随着科学计算和物理建模中深度学习的兴起，网络精度成为制约其应用的关键瓶颈。尤其是在物理信息神经网络（PINN）等需要数值精度的领域，常规网络无法达到科学仿真所需的精度，远逊于传统数值方法。学界长期困惑于：为何“通用逼近器”无法真正逼近到机器极限？",
