                "method": "研究团队提出“多阶段神经网络”(MSNN)架构：将训练过程划分为多个阶段，每一阶段新建一个网络专门学习上阶段的残差函数。\n① 第一阶段：用常规网络训练，获得基础解u₀(x)\n② 第二阶段：分析残差e₁(x)=u_g(x)-u₀(x)，估计其幅值和主导频率\n③ 针对残差特性设计专用网络：归一化幅值、调整权重缩放因子κ、使用正弦激活函数捕捉高频\n④ 训练新网络拟合归一化残差，与原网络叠加\n⑤ 重复2-4步，每阶段专门捕捉前一阶段的残差特征\n这种“残差分治”策略结合高频激活函数（如正弦）与尺度调节因子κ，使网络能捕捉细微高频变化，并以指数级速度收敛。",
