                        "subtitle": "粘弹性:时间依赖行为的捕捉",
                        "content": "粘弹性材料的力学行为依赖于时间和加载历史,表现为蠕变、松弛、滞后等现象。描述这些行为需要涉及时间导数的本构方程,如Maxwell模型或Kelvin-Voigt模型。PINN可以将这些演化方程直接嵌入损失函数,或者基于自由能和耗散势函数构建热力学一致的框架。Abdolazizi等人提出的粘弹性本构人工神经网络(vCANN)用多个子网络分别学习松弛时间和系数,成功捕捉了各向异性材料在大变形下的非线性粘弹性行为。对于涉及地质力学和流体流动的多物理耦合问题,物理约束学习(physics constrained learning)将Maxwell方程与渗流方程联合求解,展现了PINN处理复杂耦合系统的能力。最新的神经常微分方程(NODE)方法通过满足凸性条件先验,能从实验数据中准确恢复Helmholtz自由能和蠕变势,为粘弹性反问题提供了强有力工具。"
