                        "subtitle": "痛点与破局",
                        "content": "长期以来，医生和研究者面临着一个两难选择：直接测量（如导管介入）不仅昂贵且有创伤风险；而非侵入式成像（如MRI、CT）虽然安全，但往往受到时空分辨率的限制，看不清细节。传统的计算流体力学（CFD）虽然精确，但极度依赖精确的边界条件，且计算耗时漫长，难以满足临床的实时需求。\n\n为了解决这个问题，研究者提出了物理信息神经网络（PINNs）。这不仅是一个“黑盒”模型，它将描述流体运动的铁律——不可压缩纳维-斯托克斯方程（Navier-Stokes equations）——直接嵌入到神经网络的损失函数中。这意味着，模型不仅在学习数据，更是在“服从”物理定律。",
                        "keyPoints": [
                            "核心机制：将物理方程（PDEs）作为正则化项加入损失函数",
                            "双重优势：既利用了自动微分消除了数值截断误差，又通过物理约束解决了数据稀缺问题",
                            "灵活性：能同时处理正向模拟（预测血流）和反向问题（推断参数）"
                        ]
