                "limitations": "局限性主要在于坐标变换的依赖：目前的方法依赖于能建立“一对一”映射的拓扑结构，对于带孔洞或极度复杂的拓扑（如多连通域），仍需结合区域分解（Domain Decomposition）技术才能处理。此外，目前尚未在高雷诺数湍流问题上进行验证。"
