                "significance": "这项研究提出了一种名为Ψ-NN（读作Psi-NN）的通用框架。它不仅能显著提高求解精度和收敛速度，更重要的是，它让神经网络具有了「白盒」属性——提取出的矩阵直接对应物理特征。这为发现未知的物理规律和构建高效的代理模型开辟了新路径。",
                "method": "整体思路是「蒸馏-提取-重构」三部曲：\n\n① 物理信息蒸馏：\n找一个「老师」（Teacher，通常是标准PINN）负责通过PDE损失学习物理场；「学生」（Student，普通MLP）只负责模仿老师的输出，但要接受强力的L2正则化约束。这样就把「学物理」和「简化参数」两个任务解耦了。\n\n② 结构提取（核心创新）：\n在正则化作用下，学生网络的权重会自动「聚团」。研究者使用层次聚类算法（HAC）识别这些参数簇，发现它们不仅数值趋同，还呈现出明显的符号关系（如互为相反数），这正是物理对称性的体现。\n\n③ 结构重构：\n将聚类后的中心值回填，并用一个「关系矩阵R」锁定参数间的关系（如共享、变号、置换）。最终得到的是一个极致稀疏且内嵌物理结构的全新网络。",
