                "method": "FFV-PINN 的核心思路包含两大法宝：\n\n① 「简化有限体积法（Simplified FVM）」：传统 FVM 需要根据流向和强弱费力挑选离散格式。FFV-PINN 则直接利用神经网络可以输出任意点数值的特性，直接预测控制体表面的物理量。这不仅消除了人为选择格式的麻烦，还让算法具备了优异的色散和零耗散特性。\n\n② 「残差校正损失（Residual Correction Loss）」：借鉴流体算法中经典的 SIMPLE 思想。研究者推导出一种修正机制，根据当前预测值与物理定律的偏差，计算出一个「校正方向」，并将其转化为损失函数。这就像是给神经网络的优化过程安装了一个 GPS，引导参数更平滑、快速地向符合物理规律的方向更新。",
