                "field": "物理信息深度学习正成为求解偏微分方程的新范式。核心术语包括：物理信息神经网络（PINNs），将物理方程嵌入损失函数的网络；深度算子网络（DeepONet），学习函数到函数映射的强力架构；以及自动微分（AD），计算物理导数的数学引擎。",
