    "titleEN": "PINN-FORM: A new physics-informed neural network for reliability analysis with partial differential equation",
    "author": "Zeng Meng, Qiaochu Qian, Mengqiang Xu, Bo Yu ✉, Ali Rıza Yıldız, Seyedali Mirjalili",
    "unit": "合肥工业大学土木与水利工程学院应用力学研究所",
